import{_ as a,o as r,c as t,a6 as i}from"./chunks/framework.DNkVJs23.js";const f=JSON.parse('{"title":"Политика конфиденциальности","description":"Политика конфиденциальности — Sapphire Star Codex","frontmatter":{"description":"Политика конфиденциальности — Sapphire Star Codex","head":[["link",{"rel":"canonical","href":"https://eurekaffeine.github.io/sapphire-star-codex/ru/privacy/"}],["meta",{"property":"og:url","content":"https://eurekaffeine.github.io/sapphire-star-codex/ru/privacy/"}],["meta",{"property":"og:title","content":"Политика конфиденциальности | Sapphire Star Codex"}],["meta",{"property":"og:description","content":"Политика конфиденциальности — Sapphire Star Codex"}]]},"headers":[],"relativePath":"ru/privacy/index.md","filePath":"ru/privacy/index.md"}'),o={name:"ru/privacy/index.md"};function n(p,e,l,h,c,s){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="политика-конфиденциальности" tabindex="-1">Политика конфиденциальности <a class="header-anchor" href="#политика-конфиденциальности" aria-label="Permalink to &quot;Политика конфиденциальности&quot;">​</a></h1><p>Действует с 31 октября 2026 г. Последнее изменение исходного текста: 10 ноября 2026 г. Перевод: 14 ноября 2026 г.</p><p>Политика относится к приложениям Sapphire Star Codex для iOS, Android и HarmonyOS и этому сайту. Разработчик: <strong>eurekaffeine (刘耀晨)</strong>. Контакт: <a href="mailto:eurekaffeine.work@gmail.com" target="_blank" rel="noreferrer">eurekaffeine.work@gmail.com</a>. Набор функций зависит от платформы; регистрация не требуется.</p><h2 id="локальные-данные" tabindex="-1">Локальные данные <a class="header-anchor" href="#локальные-данные" aria-label="Permalink to &quot;Локальные данные&quot;">​</a></h2><p>Приложение сохраняет на устройстве настройки игры, языка и оформления, историю поиска и состояние навигации, избранное, комплекты и их названия, запасы украшений, талисманов и брони. Они используются для функций приложения и не отправляются разработчику. Разработчик не предоставляет учётные записи или облачную синхронизацию.</p><h2 id="разрешения-и-автоматическии-сбор" tabindex="-1">Разрешения и автоматический сбор <a class="header-anchor" href="#разрешения-и-автоматическии-сбор" aria-label="Permalink to &quot;Разрешения и автоматический сбор&quot;">​</a></h2><p>В приложении нет SDK рекламы, отслеживания, статистики использования или автоматической отправки отчётов о сбоях. Текущие функции не требуют доступа к контактам, местоположению, камере, микрофону или фотографиям и не собирают рекламные идентификаторы. Система и магазины могут обрабатывать сведения об установке или диагностике по своим правилам. Диагностика, переданная разработчику платформой, используется только для устранения проблем.</p><h2 id="обращения-и-внешние-сервисы" tabindex="-1">Обращения и внешние сервисы <a class="header-anchor" href="#обращения-и-внешние-сервисы" aria-label="Permalink to &quot;Обращения и внешние сервисы&quot;">​</a></h2><p>При добровольном обращении по email разработчик получает адрес, текст и вложения для ответа, расследования ошибок и обработки запросов о конфиденциальности, а не для маркетинга. Отправляйте лишь необходимые данные. Gmail обрабатывает почту согласно <a href="https://policies.google.com/privacy" target="_blank" rel="noreferrer">политике Google</a>.</p><p>Сайт размещён на GitHub Pages, который может получать IP-адрес и технические сведения браузера; см. <a href="https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement" target="_blank" rel="noreferrer">политику GitHub</a>. Дополнительная аналитика посещений, рекламные cookie и пиксели отслеживания не используются. Поиск выполняется в браузере, где могут сохраняться настройки. Внешние сервисы применяют собственные правила и могут обрабатывать сведения за пределами вашей страны.</p><h2 id="взносы-и-резервные-копии" tabindex="-1">Взносы и резервные копии <a class="header-anchor" href="#взносы-и-резервные-копии" aria-label="Permalink to &quot;Взносы и резервные копии&quot;">​</a></h2><p>Alipay или WeChat Pay обрабатывает взносы по собственным условиям. Сайт показывает только статичные коды, без платёжного SDK и получения учётных данных. Разработчик может видеть сведения, которые платформа предоставляет получателю: сумму, время, отображаемое имя и примечание. Они нужны для учёта взносов и решения проблем и хранятся по правилам платформы и применимым обязательствам. В зависимости от настроек данные приложения могут попадать в резервные копии устройства или облака; разработчик не может читать или удалять такие копии.</p><h2 id="передача-хранение-и-удаление" tabindex="-1">Передача, хранение и удаление <a class="header-anchor" href="#передача-хранение-и-удаление" aria-label="Permalink to &quot;Передача, хранение и удаление&quot;">​</a></h2><p>Разработчик не продаёт и не сдаёт в аренду персональные данные и не передаёт их для рекламы. Почту обрабатывает указанный поставщик. Фактически имеющиеся сведения могут быть предоставлены при требовании закона или явном запросе пользователя.</p><p>Локальные данные можно удалить в приложении или настройках системы. Удаление приложения с сохранением данных не стирает их; резервными копиями нужно управлять отдельно, поскольку они могут восстановить данные. Настройки сайта сохраняются до удаления или очистки браузером. Сообщения хранятся лишь для обработки обращения, последующего общения или выполнения правовых обязанностей. Поставщики управляют собственными журналами и копиями. Для доступа, исправления или удаления отправленных данных обратитесь к разработчику; закон может требовать их сохранения. К данным, оставшимся только на устройстве, у разработчика нет удалённого доступа.</p><h2 id="безопасность-дети-и-изменения" tabindex="-1">Безопасность, дети и изменения <a class="header-anchor" href="#безопасность-дети-и-изменения" aria-label="Permalink to &quot;Безопасность, дети и изменения&quot;">​</a></h2><p>Локальное хранение защищено механизмами операционной системы. Сайт использует HTTPS. Доступ к сообщениям ограничен поддержкой и вопросами конфиденциальности, с защитой почтового сервиса. Приложение не запрашивает личный профиль или дату рождения и не собирает намеренно сведения о детях. Родитель может запросить удаление информации, отправленной ребёнком.</p><p>При изменении практик обновляются политика и дата. Важные изменения сообщаются на сайте или в обновлении приложения. Разрешения и согласия для новых функций запрашиваются отдельно; эта политика их не заменяет.</p><p><strong>eurekaffeine (刘耀晨)</strong> — <a href="mailto:eurekaffeine.work@gmail.com" target="_blank" rel="noreferrer">eurekaffeine.work@gmail.com</a></p>',19)])])}const u=a(o,[["render",n]]);export{f as __pageData,u as default};
